const tls = require('tls');

// Credenciales por variable de entorno del contenedor Docker -> NUNCA en el JSON del workflow.
const IMAP_HOST = $env.IMAP_HOST || 'imap.gmail.com';
const IMAP_PORT = Number($env.IMAP_PORT || 993);
const IMAP_USER = $env.IMAP_USER;
const IMAP_PASS = $env.IMAP_APP_PASSWORD;
const DRAFTS_FOLDER = $env.IMAP_DRAFTS_FOLDER || '[Gmail]/Drafts';

if (!IMAP_USER || !IMAP_PASS) {
  throw new Error('Faltan IMAP_USER / IMAP_APP_PASSWORD como variables de entorno del contenedor telara-n8n.');
}

function connect(host, port) {
  return new Promise((resolve, reject) => {
    const socket = tls.connect(port, host, { servername: host }, () => resolve(socket));
    socket.once('error', reject);
  });
}

function waitFor(socket, isDone, timeoutMs = 15000) {
  return new Promise((resolve, reject) => {
    let buf = '';
    const timer = setTimeout(() => {
      socket.removeListener('data', onData);
      reject(new Error('Timeout IMAP, ultima respuesta: ' + buf.slice(-300)));
    }, timeoutMs);
    function onData(chunk) {
      buf += chunk.toString('utf8');
      if (isDone(buf)) {
        clearTimeout(timer);
        socket.removeListener('data', onData);
        resolve(buf);
      }
    }
    socket.on('data', onData);
  });
}

const taggedOk = (tag) => (buf) => new RegExp('(^|\\r\\n)' + tag + ' (OK|NO|BAD)', 'i').test(buf);

const item = $input.first().json;
const toAddr = item.email;
const subject = (item.asunto && item.asunto.trim()) ? ('Re: ' + item.asunto) : 'Re: tu consulta';
const bodyText = item.cuerpo_borrador ||
  'Hola,\n\nRecibimos tu consulta. El equipo de la clinica se va a comunicar con vos.\n\nSaludos,\nEquipo de Odontologia Sonrisas';
const inReplyTo = item.message_id_header || '';

const headerLines = [
  'From: ' + IMAP_USER,
  'To: ' + toAddr,
  'Subject: ' + subject,
  'Date: ' + new Date().toUTCString(),
  'MIME-Version: 1.0',
  'Content-Type: text/plain; charset=UTF-8',
  'Content-Transfer-Encoding: 8bit'
];
if (inReplyTo) {
  headerLines.push('In-Reply-To: ' + inReplyTo);
  headerLines.push('References: ' + inReplyTo);
}
const rfc822 = headerLines.join('\r\n') + '\r\n\r\n' + String(bodyText).replace(/\n/g, '\r\n');
const size = Buffer.byteLength(rfc822, 'utf8');

let socket, draftCreated = false, errorMsg = '';
try {
  socket = await connect(IMAP_HOST, IMAP_PORT);
  await waitFor(socket, (b) => b.includes('* OK'));

  function imapQuote(str) {
  return '"' + String(str).trim().replace(/\\/g, '\\\\').replace(/"/g, '\\"') + '"';
}
socket.write('a1 LOGIN ' + imapQuote(IMAP_USER) + ' ' + imapQuote(IMAP_PASS) + '\r\n');
  const login = await waitFor(socket, taggedOk('a1'));
  if (!/a1 OK/i.test(login)) throw new Error('LOGIN rechazado por el servidor IMAP.');

  socket.write('a2 APPEND "' + DRAFTS_FOLDER + '" (\\Draft) {' + size + '}\r\n');
  await waitFor(socket, (b) => /\+ ?/.test(b));

  socket.write(rfc822 + '\r\n');
  const append = await waitFor(socket, taggedOk('a2'), 20000);
  if (!/a2 OK/i.test(append)) throw new Error('APPEND rechazado: revisar nombre de carpeta DRAFTS_FOLDER (' + DRAFTS_FOLDER + ').');

  draftCreated = true;
  socket.write('a3 LOGOUT\r\n');
  await waitFor(socket, (b) => /a3 OK|BYE/i.test(b), 5000).catch(() => {});
} catch (e) {
  errorMsg = e.message || String(e);
} finally {
  if (socket) socket.end();
}

return [{
  json: {
    ...item,
    id: draftCreated ? ('imap-draft-' + Date.now()) : undefined,
    error: draftCreated ? undefined : (errorMsg || 'No se pudo crear el borrador via IMAP APPEND')
  }
}];
